    fun load(mg: IntArray, eg: IntArray): Boolean {
        if (DATA.isEmpty()) return false
        val parts = DATA.split(';')
        if (parts.size != mg.size) return false
        for (i in parts.indices) {
            val (a, b) = parts[i].split(',')
            mg[i] = a.toInt(); eg[i] = b.toInt()
        }
        return true
